import{_ as a,o,c as t,ae as s}from"./chunks/framework.Dn6zxbF8.js";const u=JSON.parse('{"title":"Schema source directories","description":"","frontmatter":{"id":"4711775939","title":"Schema source directories","state":"Approved","created":"2026-10-07T00:00:00.000Z","tags":["directory","protobuf","wit","opentelemetry","weaver"],"category":"Platform"},"headers":[],"relativePath":"adrs/4711775939/README.md","filePath":"adrs/4711775939/README.md"}'),n={name:"adrs/4711775939/README.md"};function r(i,e,c,l,d,p){return o(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="schema-source-directories" tabindex="-1">Schema source directories <a class="header-anchor" href="#schema-source-directories" aria-label="Permalink to &quot;Schema source directories&quot;">​</a></h1><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p><a href="./../9316364013/README.html">ADR#9316364013</a> reserves <code>proto/</code>, <code>wit/</code> and <code>otel/</code> for schema sources. This ADR fixes the layout inside each.</p><p>Protocol Buffers settled on <code>proto/</code> long ago, and the WIT toolchain defaults to <code>wit/</code>. OpenTelemetry registries had no consensus: the upstream repository uses <code>model/</code> because the directory predates Weaver, and our own repositories used <code>semconv/</code>, <code>telemetry/</code> and <code>otel/semconv/</code>. <code>semconv</code> also names a conventional commit type and <code>telemetry/</code> is reserved for observability code inside packages, so neither can name the directory.</p><h2 id="resolution" tabindex="-1">Resolution <a class="header-anchor" href="#resolution" aria-label="Permalink to &quot;Resolution&quot;">​</a></h2><ul><li>You <strong>MUST NOT</strong> name a schema directory after the tool that consumes it, and you <strong>MUST NOT</strong> use <code>model/</code>, <code>schemas/</code>, <code>semconv/</code> or <code>telemetry/</code>.</li><li>You <strong>MUST</strong> keep only schema sources, and the configuration that describes them as a module, in the directory. Configuration that drives a tool, such as code generation, goes under <code>.config/&lt;tool&gt;/</code>. Generated code <strong>MUST</strong> live in the language workspace that consumes it.</li><li>You <strong>MAY</strong> place a schema directory next to a single component or service when the schema belongs to that component alone. It <strong>MUST</strong> still use the same name.</li></ul><h3 id="protocol-buffers" tabindex="-1">Protocol Buffers <a class="header-anchor" href="#protocol-buffers" aria-label="Permalink to &quot;Protocol Buffers&quot;">​</a></h3><ul><li><p>You <strong>MUST</strong> keep <code>buf.yaml</code> in the v2 format and <code>buf.lock</code> inside <code>proto/</code>, so the module carries its own configuration and lock.</p></li><li><p>You <strong>MUST</strong> keep <code>buf.gen.yaml</code> under <code>.config/buf/</code>, and <strong>MUST</strong> run buf from the repository root, passing the directory or template: <code>buf lint proto</code>, <code>buf dep update proto</code>, <code>buf generate --template .config/buf/buf.gen.yaml</code>.</p></li><li><p>You <strong>MUST</strong> mirror the package name in the directory path and end it with the version segment, as buf lint requires.</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.</span></span>
<span class="line"><span>├── .config/buf/buf.gen.yaml</span></span>
<span class="line"><span>└── proto</span></span>
<span class="line"><span>    ├── buf.yaml            # version: v2</span></span>
<span class="line"><span>    ├── buf.lock</span></span>
<span class="line"><span>    └── &lt;package path&gt;/*.proto   # acme.billing.v1 is acme/billing/v1/</span></span></code></pre></div></li></ul><h3 id="webassembly-interface-types" tabindex="-1">WebAssembly Interface Types <a class="header-anchor" href="#webassembly-interface-types" aria-label="Permalink to &quot;WebAssembly Interface Types&quot;">​</a></h3><ul><li><p>You <strong>MUST</strong> keep one WIT package directly under <code>wit/</code>, with fetched dependencies in <code>wit/deps/</code>.</p></li><li><p>You <strong>MUST</strong> use <code>wit/&lt;package&gt;/</code> when a repository publishes more than one package.</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.</span></span>
<span class="line"><span>└── wit</span></span>
<span class="line"><span>    ├── world.wit</span></span>
<span class="line"><span>    ├── &lt;interface&gt;.wit</span></span>
<span class="line"><span>    ├── deps.toml</span></span>
<span class="line"><span>    ├── deps.lock</span></span>
<span class="line"><span>    └── deps/</span></span></code></pre></div></li></ul><h3 id="opentelemetry-semantic-conventions" tabindex="-1">OpenTelemetry semantic conventions <a class="header-anchor" href="#opentelemetry-semantic-conventions" aria-label="Permalink to &quot;OpenTelemetry semantic conventions&quot;">​</a></h3><ul><li><p>You <strong>MUST</strong> follow Weaver&#39;s vocabulary for the second level: <code>registry/</code>, <code>templates/</code> and <code>policies/</code>, one per flag that consumes it.</p></li><li><p>You <strong>MUST</strong> name the registry manifest <code>manifest.yaml</code>.</p></li><li><p>You <strong>MAY</strong> omit <code>templates/</code> and <code>policies/</code> when a shared Weaver package already provides them.</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.</span></span>
<span class="line"><span>└── otel</span></span>
<span class="line"><span>    ├── registry            # --registry</span></span>
<span class="line"><span>    │   ├── manifest.yaml</span></span>
<span class="line"><span>    │   └── &lt;vendor&gt;/&lt;domain&gt;/*.yaml</span></span>
<span class="line"><span>    ├── templates           # --templates, Weaver reads templates/registry/&lt;target&gt;/</span></span>
<span class="line"><span>    └── policies            # --policy</span></span></code></pre></div></li></ul><h2 id="links" tabindex="-1">Links <a class="header-anchor" href="#links" aria-label="Permalink to &quot;Links&quot;">​</a></h2><ul><li><a href="./../9316364013/README.html">ADR#9316364013</a>: Reserved repository directories</li><li><a href="https://buf.build/docs/configuration/v2/buf-yaml/" target="_blank" rel="noreferrer">buf configuration, v2 <code>buf.yaml</code></a></li><li><a href="https://github.com/bytecodealliance/cargo-component/blob/main/src/metadata.rs" target="_blank" rel="noreferrer">cargo-component default WIT directory</a></li><li><a href="https://github.com/bytecodealliance/wasm-pkg-tools/blob/main/crates/wkg/src/wit.rs" target="_blank" rel="noreferrer">wkg <code>--wit-dir</code> default</a></li><li><a href="https://github.com/open-telemetry/weaver/blob/main/crates/weaver_cli/README.md" target="_blank" rel="noreferrer">Weaver registry commands</a></li><li><a href="https://github.com/open-telemetry/weaver/blob/main/docs/define-your-own-telemetry-schema.md" target="_blank" rel="noreferrer">Weaver, define your own telemetry schema</a></li></ul>`,14)])])}const m=a(n,[["render",r]]);export{u as __pageData,m as default};
